import { SyntheticEvent } from 'react';
import type { AvatarSize } from '../../Avatar.types';
export interface AvatarImageProps {
    /** Source URL for the image */
    src: string;
    /** Generated alt text for accessibility */
    generatedAltText: string;
    /** Error handler for image load failures */
    onError?: (error: SyntheticEvent<HTMLImageElement, Event>) => void;
    /** Success handler for image load */
    onLoad?: (event: SyntheticEvent<HTMLImageElement, Event>) => void;
    /** User name for showing initials during loading */
    userName?: string;
    /** Avatar size for initials fallback */
    size?: AvatarSize;
}
